__NUXT_JSONP__("/th/how-to-apply", {data:[{details:{slug:"th",pageTitle:"คุณต้องการสมัครวีซ่าประเภทใด | Mentor Language Institute",pageDescription:"กรุณาเลือกข้อมูลวีซ่าของคุณจากตัวเลือกด้านล่าง",title:"คุณต้องการสมัครวีซ่าประเภทใด",image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fvisa.jpg",category:[{title:"กรุณาเลือกข้อมูลวีซ่าของคุณจากตัวเลือกด้านล่าง:",btn_visa:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fvisa_btn-th.png",link:"\u002Fth\u002Fhow-to-apply\u002Fstudent-visa-f1"},btn_others:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fothers_btn-th.png",link:"\u002Fth\u002Fhow-to-apply\u002Fothers"}}],content:{subtitle:"Any questions?",description:["โดยปกติคุณจะต้องมีวีซ่านักเรียน เพื่อการเรียนระยะยาวในประเทศสหรัฐอเมริกา.\u003Cbr \u002F\u003Eหากคุณไม่ทราบว่าคุณต้องการวีซ่าหรือไม่โปรดติดต่อเรา","เรามีให้บริการถึง 8 ภาษา."],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fcontact-us-th.jpg",link:"\u002Fth\u002Fcontact"}},dir:"\u002Fhow-to-apply",path:"\u002Fhow-to-apply\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:29.656Z",updatedAt:"2025-05-26T12:06:27.792Z"}}],fetch:{},mutations:void 0});